const TIMEZONE = 'America/Sao_Paulo';

function dataLocal(date) {
  const partes = new Intl.DateTimeFormat('en-CA', {
    timeZone: TIMEZONE,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).formatToParts(date);

  const get = (tipo) => partes.find(p => p.type === tipo).value;

  return `${get('year')}-${get('month')}-${get('day')}`;
}

function diaUTC(data) {
  const [ano, mes, dia] = data.split('-').map(Number);
  return Date.UTC(ano, mes - 1, dia);
}

function formatarDataISO(dataISO) {
  if (!dataISO) return 'Não informado';

  return DateTime
    .fromISO(dataISO)
    .setZone(TIMEZONE)
    .toFormat('dd/MM/yyyy');
}

const hojeTexto = dataLocal(new Date());
const hoje = diaUTC(hojeTexto);

const linhas = items.map((item) => {
  const fields = item.json.fields ?? item.json;

  const limiteOriginal = new Date(fields.DataLimiteComercial);
  const limiteTexto = dataLocal(limiteOriginal);
  const limite = diaUTC(limiteTexto);

  const diasRestantes = Math.max(
    0,
    Math.round((limite - hoje) / (1000 * 60 * 60 * 24))
  );

  const nomeCliente = fields.NomedoCliente || 'Não informado';
  const endereco = fields.Title || 'Não informado';
  const motivo = fields.Motivo || 'Não informado';
  const email = fields.E_x002d_MaildoCliente || 'Não informado';
  const telefone = fields.ContatodoCliente || 'Não informado';

  const avisoPrevio = formatarDataISO(fields.AvisoPrevio);
  const prazoComercial = formatarDataISO(fields.DataLimiteComercial);

  return `👤 Nome: ${nomeCliente}
📍 Endereço: ${endereco}
📝 Motivo: ${motivo}
📧 E-mail: ${email}
📞 Telefone: ${telefone}
📅 Aviso Prévio: ${avisoPrevio}

📅 Prazo Comercial: ${prazoComercial}
⏳ Dias restantes: ${diasRestantes}`;
});

const mensagem = `🔔 LEMBRETE — RECUPERAÇÃO DE CLIENTES

Os clientes abaixo ainda estão dentro do prazo comercial para tentativa de recuperação:

${linhas.join('\n\n────────────────────\n\n')}

Favor acompanhar as tratativas e registrar o resultado na enquete correspondente.`;

return [
  {
    json: {
      mensagem
    }
  }
];
